window.kbPageData["views/entry/k-71c4db1c83f4ef71"] = {"key":"entry/k-71c4db1c83f4ef71","state":{"route":"entry/k-71c4db1c83f4ef71"},"node":{"id":"k-71c4db1c83f4ef71","mode":"k","title":"人均量的跨期倍数","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["人均量的跨期倍数等于总量倍数除以人数倍数","人均量的跨期倍数等于总量的跨期倍数除以人数的跨期倍数"],"qs":["江苏 2023 A类 行测#119","江苏 2023 B类 行测#119"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":2,"repeatPositions":0,"directorySummary":"在两期统计口径一致、人数均大于零且基期总量大于零时，现期人均量是基期的多少倍，等于总量的跨期倍数除以人数的跨期倍数。","review":{"definition":"在两期统计口径一致、人数均大于零且基期总量大于零时，现期人均量是基期的多少倍，等于总量的跨期倍数除以人数的跨期倍数。","explanation":"人均量等于总量除以人数，所以两期人均量相除，可将两期总量和两期人数分别作比。本题中，2021年移动互联网接入总流量是2012年的252倍，上网人数增长83.0%，即为2012年的1.83倍。因此人均接入流量约为2012年的252 ÷ 1.83 ≈ 138倍，对应D项。","references":[],"evidence":"是2012年的252倍；互联网上网人数10.3亿人，比2012年增长\n83.0%。","disposition":"独立词条","basis":"据原题和解析编释。","title":"人均量的跨期倍数","related":[],"examFocus":{"江苏 2023 A类 行测#119":"用接入总流量的跨期倍数除以上网人数的跨期倍数，得到人均接入流量的跨期倍数。","江苏 2023 B类 行测#119":"用接入总流量的跨期倍数除以上网人数的跨期倍数，得到人均接入流量的跨期倍数。"}},"readings":[{"origin":"k-71c4db1c83f4ef71","title":"人均量的跨期倍数","qs":["江苏 2023 B类 行测#119"],"definition":"在两期统计口径一致、人数均大于零且基期总量大于零时，现期人均量是基期的多少倍，等于总量的跨期倍数除以人数的跨期倍数。","explanation":"人均量等于总量除以人数，所以两期人均量相除，可将两期总量和两期人数分别作比。本题中，2021年移动互联网接入总流量是2012年的252倍，上网人数增长83.0%，即为2012年的1.83倍。因此人均接入流量约为2012年的252 ÷ 1.83 ≈ 138倍，对应D项。","evidence":"是2012年的252倍；互联网上网人数10.3亿人，比2012年增长\n83.0%。","doubt":"","references":[]},{"origin":"k-c678b1a94ea605fd","title":"人均量的跨期倍数","qs":["江苏 2023 A类 行测#119"],"definition":"各期人均量等于当期总量除以当期人数。两期统计口径一致且基期人均量非零时，人均量的跨期倍数等于总量的跨期倍数除以人数的跨期倍数。","explanation":"第119题中，2021年移动互联网接入流量是2012年的252倍。互联网上网人数比2012年增长83.0%，即为2012年的1.83倍。用总量倍数除以人数倍数，得252÷1.83≈137.7，因此选D（138倍）。","evidence":"人均移动互联网接入流量是2012年的","doubt":"","references":[]}]},"questions":{"江苏 2023 A类 行测#119":{"paper":"江苏 2023 A类 行测","n":119,"mod":"资料分析","src":["22304fe4c340e19d7902.pdf",26],"asrc":["be17f9afe070cf13a0fb.pdf",37],"card":"6efab3a52eae5fab440ddd86","links":[{"id":"k-71c4db1c83f4ef71","role":"解题依据","why":"各期人均量等于当期总量除以当期人数，两期人均量之比可化为总量倍数与人数倍数之比。"}]},"江苏 2023 B类 行测#119":{"paper":"江苏 2023 B类 行测","n":119,"mod":"资料分析","src":["22262c34d18cd68fbee4.pdf",23],"asrc":["b08f2713d73015eac675.pdf",39],"card":"7c547e36348938e8278b6299","links":[{"id":"k-71c4db1c83f4ef71","role":"解题依据","why":"人均量等于总量除以人数，两期人均量之比可化为总量倍数除以人数倍数，人数倍数等于一加人数增长率。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-71c4db1c83f4ef71":[["江苏 2023 A类 行测#119"],["江苏 2023 B类 行测#119"]]}};
